//! Icons for kinds of files, as the file tree of codiff, `@pierre/trees`,
//! draws them: a Go file gets the gopher, a TypeScript file TypeScript's
//! logo, each in a color of its own.
//!
//! The SVGs live in `crates/app/assets/icons/file/<token>.svg` (they use
//! `currentColor` and per-path opacity, so tint them with [`color`]).
//! The tables in `data.rs` and the SVGs are generated by `tools/gen.py`
//! from a Go file of the package's tables.
//!
//! The icons are © 2025 Pierre Computer Company, licensed under the Apache
//! License 2.0; see `LICENSE-icons` in this crate.

mod data;

pub use data::TOKENS;

/// Token of the files of no known kind.
pub const DEFAULT: &str = "default";

fn lookup<V: Copy>(table: &'static [(&'static str, V)], key: &str) -> Option<V> {
    table
        .binary_search_by(|(k, _)| (*k).cmp(key))
        .ok()
        .map(|i| table[i].1)
}

/// Returns the kind of a file by its path: by its whole name (as
/// `Dockerfile`), else by its extensions, the longest first (`.d.ts`
/// before `.ts`), else [`DEFAULT`]. Matching ignores ASCII case.
pub fn token(path: &str) -> &'static str {
    let name = path.rsplit('/').next().unwrap_or(path).to_ascii_lowercase();
    if let Some(t) = lookup(data::BY_NAME, &name) {
        return t;
    }
    for (i, _) in name.match_indices('.') {
        let ext = &name[i + 1..];
        if let Some(t) = lookup(data::OVERRIDES, ext).or_else(|| lookup(data::BY_EXTENSION, ext)) {
            return t;
        }
    }
    DEFAULT
}

/// The asset path of a token's SVG, relative to the app's asset root:
/// `icons/file/<token>.svg`.
pub fn icon_path(token: &str) -> String {
    format!("icons/file/{token}.svg")
}

/// The icon's color for the light or dark theme, as `0xRRGGBB` (opaque; no
/// icon color carries alpha). Unknown tokens get the default icon's color.
pub fn color(token: &str, dark: bool) -> u32 {
    let table = if dark {
        data::DARK_COLORS
    } else {
        data::LIGHT_COLORS
    };
    lookup(table, token)
        .or_else(|| lookup(table, DEFAULT))
        .unwrap_or(0x84848a)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tokens_by_path() {
        for (path, want) in [
            ("main.go", "go"),
            ("web/src/App.tsx", "react"),
            ("web/src/app.ts", "typescript"),
            ("types/global.d.ts", "typescript"),
            ("lib/index.mjs", "javascript"),
            ("Dockerfile", "docker"),
            ("deploy/docker-compose.yml", "docker"),
            (".gitignore", "git"),
            ("README.md", "markdown"),
            ("pnpm-lock.yaml", "yml"),
            ("bun.lock", "bun"),
            ("vite.config.ts", "vite"),
            ("styles/site.scss", "sass"),
            ("logo.PNG", "image"),
            ("LICENSE", "default"),
            ("Makefile.unknown-kind", "default"),
            ("dist/release.tar.gz", "default"), // zip: no icon upstream
        ] {
            assert_eq!(token(path), want, "{path}");
        }
    }

    #[test]
    fn tables_sorted() {
        fn sorted<V>(t: &[(&str, V)]) -> bool {
            t.windows(2).all(|w| w[0].0 < w[1].0)
        }
        assert!(sorted(data::BY_NAME));
        assert!(sorted(data::BY_EXTENSION));
        assert!(sorted(data::OVERRIDES));
        assert!(sorted(data::LIGHT_COLORS));
        assert!(sorted(data::DARK_COLORS));
        assert!(TOKENS.windows(2).all(|w| w[0] < w[1]));
    }

    #[test]
    fn icons() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../app/assets");
        assert!(TOKENS.contains(&DEFAULT));
        for &t in TOKENS {
            assert!(!token(&format!("x.{t}")).is_empty());
            let svg = std::fs::read_to_string(dir.join(icon_path(t)))
                .unwrap_or_else(|e| panic!("{t}: {e}"));
            assert!(svg.starts_with("<svg"), "{t}");
            assert!(
                lookup(data::LIGHT_COLORS, t).is_some(),
                "{t}: no light color"
            );
            assert!(lookup(data::DARK_COLORS, t).is_some(), "{t}: no dark color");
        }
        // Every token the tables can return has an icon.
        for (_, t) in data::BY_NAME
            .iter()
            .chain(data::BY_EXTENSION)
            .chain(data::OVERRIDES)
        {
            assert!(TOKENS.contains(t), "{t} has no icon");
        }
        assert_eq!(icon_path("go"), "icons/file/go.svg");
        assert_ne!(color("go", true), color("go", false));
        assert_eq!(color("nope", false), color(DEFAULT, false));
    }
}
